mod help;
mod tui;

use std::env;
use std::path::PathBuf;
use std::process::ExitCode;

fn print_help() {
    // Use print! (not println!) since the HELP_TEXT already ends with \n.
    print!("{}", help::HELP_TEXT);
}

fn print_init() {
    print!("{}", help::INIT_TEXT);
}

fn report_invalid_path(arg: &str) {
    eprintln!();
    eprintln!("Invalid path: {}", arg);
    eprintln!("`fx -h` shows help.");
}

fn parse_path(arg: &str) -> Option<PathBuf> {
    if arg.is_empty() {
        return None;
    }
    let p = PathBuf::from(arg);
    if p.is_dir() {
        // Canonicalize
        std::fs::canonicalize(&p).ok().or(Some(p))
    } else {
        None
    }
}

fn main() -> ExitCode {
    let args: Vec<String> = env::args().skip(1).collect();

    let (log_enabled, path_opt): (bool, Option<PathBuf>) = match args.len() {
        0 => (false, None),
        1 => {
            let a = &args[0];
            match a.as_str() {
                "-h" | "--help" => {
                    print_help();
                    return ExitCode::SUCCESS;
                }
                "--init" => {
                    print_init();
                    return ExitCode::SUCCESS;
                }
                "-l" | "--log" => (true, None),
                _ => match parse_path(a) {
                    Some(p) => (false, Some(p)),
                    None => {
                        report_invalid_path(a);
                        return ExitCode::SUCCESS;
                    }
                },
            }
        }
        2 => {
            let (first, second) = (&args[0], &args[1]);
            if first == "-l" || first == "--log" {
                match parse_path(second) {
                    Some(p) => (true, Some(p)),
                    None => {
                        report_invalid_path(second);
                        return ExitCode::SUCCESS;
                    }
                }
            } else {
                print_help();
                return ExitCode::SUCCESS;
            }
        }
        _ => {
            print_help();
            return ExitCode::SUCCESS;
        }
    };

    // Launch TUI
    let start_path = match path_opt {
        Some(p) => p,
        None => match env::current_dir() {
            Ok(p) => p,
            Err(_) => {
                eprintln!("Error: Cannot determine current directory");
                return ExitCode::SUCCESS;
            }
        },
    };

    match tui::run(start_path, log_enabled) {
        Ok(_) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("Error: {}", e);
            ExitCode::SUCCESS
        }
    }
}
