// Minimal TUI implementation for felix reimplementation.
// Focuses on the most commonly observable behavior.

use std::fs;
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::time::SystemTime;

// ----- libc FFI (minimal, Linux-only) -----
mod ffi {
    use std::os::raw::{c_int, c_short, c_ulong, c_ushort, c_uchar};

    pub const STDIN_FD: c_int = 0;
    pub const STDOUT_FD: c_int = 1;

    pub const TIOCGWINSZ: c_ulong = 0x5413;
    pub const TCSAFLUSH: c_int = 2;

    // termios structure (Linux x86_64)
    pub const NCCS: usize = 32;

    #[repr(C)]
    #[derive(Default, Clone, Copy)]
    pub struct Termios {
        pub c_iflag: u32,
        pub c_oflag: u32,
        pub c_cflag: u32,
        pub c_lflag: u32,
        pub c_line: c_uchar,
        pub c_cc: [c_uchar; NCCS],
        pub c_ispeed: u32,
        pub c_ospeed: u32,
    }

    #[repr(C)]
    #[derive(Default)]
    pub struct Winsize {
        pub ws_row: c_ushort,
        pub ws_col: c_ushort,
        pub ws_xpixel: c_ushort,
        pub ws_ypixel: c_ushort,
    }

    extern "C" {
        pub fn ioctl(fd: c_int, request: c_ulong, ...) -> c_int;
        pub fn tcgetattr(fd: c_int, termios_p: *mut Termios) -> c_int;
        pub fn tcsetattr(fd: c_int, optional_actions: c_int, termios_p: *const Termios) -> c_int;
        pub fn isatty(fd: c_int) -> c_int;
    }

    // Flag constants used for raw mode (values from Linux termios-struct(3)).
    pub const BRKINT: u32 = 0o000002;
    pub const ICRNL:  u32 = 0o000400;
    pub const INPCK:  u32 = 0o000020;
    pub const ISTRIP: u32 = 0o000040;
    pub const IXON:   u32 = 0o002000;
    pub const OPOST:  u32 = 0o000001;
    pub const CS8:    u32 = 0o000060;
    pub const ECHO:   u32 = 0o000010;
    pub const ICANON: u32 = 0o000002;
    pub const IEXTEN: u32 = 0o100000;
    pub const ISIG:   u32 = 0o000001;

    pub const VMIN: usize = 6;
    pub const VTIME: usize = 5;

    let _ = c_short;
}

struct TerminalGuard {
    original: ffi::Termios,
    restored: bool,
}

impl TerminalGuard {
    fn enter_raw() -> io::Result<Self> {
        unsafe {
            if ffi::isatty(ffi::STDIN_FD) == 0 {
                return Err(io::Error::new(io::ErrorKind::Other, "stdin is not a tty"));
            }
            let mut orig: ffi::Termios = std::mem::zeroed();
            if ffi::tcgetattr(ffi::STDIN_FD, &mut orig) != 0 {
                return Err(io::Error::last_os_error());
            }
            let mut raw = orig;
            raw.c_iflag &= !(ffi::BRKINT | ffi::ICRNL | ffi::INPCK | ffi::ISTRIP | ffi::IXON);
            raw.c_oflag &= !ffi::OPOST;
            raw.c_cflag |= ffi::CS8;
            raw.c_lflag &= !(ffi::ECHO | ffi::ICANON | ffi::IEXTEN | ffi::ISIG);
            raw.c_cc[ffi::VMIN] = 1;
            raw.c_cc[ffi::VTIME] = 0;
            if ffi::tcsetattr(ffi::STDIN_FD, ffi::TCSAFLUSH, &raw) != 0 {
                return Err(io::Error::last_os_error());
            }
            Ok(TerminalGuard { original: orig, restored: false })
        }
    }

    fn restore(&mut self) {
        if !self.restored {
            unsafe {
                ffi::tcsetattr(ffi::STDIN_FD, ffi::TCSAFLUSH, &self.original);
            }
            self.restored = true;
        }
    }
}

impl Drop for TerminalGuard {
    fn drop(&mut self) {
        self.restore();
    }
}

fn terminal_size() -> Option<(u16, u16)> {
    unsafe {
        let mut ws: ffi::Winsize = std::mem::zeroed();
        if ffi::ioctl(ffi::STDOUT_FD, ffi::TIOCGWINSZ, &mut ws) == 0 && ws.ws_col > 0 && ws.ws_row > 0 {
            Some((ws.ws_col, ws.ws_row))
        } else {
            None
        }
    }
}

#[derive(Clone)]
struct Entry {
    name: String,
    path: PathBuf,
    is_dir: bool,
    is_hidden: bool,
    modified: SystemTime,
    size: u64,
}

fn read_entries(dir: &Path, show_hidden: bool, by_time: bool) -> io::Result<Vec<Entry>> {
    let mut list = Vec::new();
    for ent in fs::read_dir(dir)? {
        let ent = match ent { Ok(e) => e, Err(_) => continue };
        let name = ent.file_name().to_string_lossy().into_owned();
        let is_hidden = name.starts_with('.');
        if is_hidden && !show_hidden {
            continue;
        }
        let md = match ent.metadata() { Ok(m) => m, Err(_) => continue };
        let modified = md.modified().unwrap_or(SystemTime::UNIX_EPOCH);
        list.push(Entry {
            name,
            path: ent.path(),
            is_dir: md.is_dir(),
            is_hidden,
            modified,
            size: md.len(),
        });
    }
    if by_time {
        list.sort_by(|a, b| b.modified.cmp(&a.modified).then(a.name.to_lowercase().cmp(&b.name.to_lowercase())));
    } else {
        // Dirs first, then files. Within each, alphabetical (case-insensitive).
        list.sort_by(|a, b| match (a.is_dir, b.is_dir) {
            (true, false) => std::cmp::Ordering::Less,
            (false, true) => std::cmp::Ordering::Greater,
            _ => a.name.to_lowercase().cmp(&b.name.to_lowercase()),
        });
    }
    Ok(list)
}

fn format_time(t: SystemTime) -> String {
    let dur = match t.duration_since(SystemTime::UNIX_EPOCH) {
        Ok(d) => d,
        Err(_) => return String::from("                ")
    };
    let secs = dur.as_secs() as i64;
    let (y, mo, d, h, mi) = unix_to_ymdhm(secs);
    format!("{:04}-{:02}-{:02} {:02}:{:02}", y, mo, d, h, mi)
}

fn unix_to_ymdhm(mut secs: i64) -> (i32, u32, u32, u32, u32) {
    // Days since 1970-01-01
    let days = secs.div_euclid(86400);
    secs = secs.rem_euclid(86400);
    let hour = (secs / 3600) as u32;
    let minute = ((secs % 3600) / 60) as u32;

    // Convert days to Y-M-D using algorithm from Howard Hinnant
    let z = days + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = (if mp < 10 { mp + 3 } else { mp - 9 }) as u32;
    let year = (y + if m <= 2 { 1 } else { 0 }) as i32;
    (year, m, d, hour, minute)
}

fn format_size(n: u64) -> String {
    if n < 1024 { return format!("{}B", n); }
    let units = ["K", "M", "G", "T", "P"];
    let mut v = n as f64 / 1024.0;
    let mut i = 0usize;
    while v >= 1024.0 && i + 1 < units.len() {
        v /= 1024.0;
        i += 1;
    }
    if v >= 100.0 {
        format!("{:.0}{}", v, units[i])
    } else if v >= 10.0 {
        format!("{:.1}{}", v, units[i])
    } else {
        format!("{:.2}{}", v, units[i])
    }
}

fn format_mode(path: &Path) -> String {
    use std::os::unix::fs::MetadataExt;
    match fs::metadata(path) {
        Ok(m) => {
            let mode = m.mode() & 0o777;
            format!("{:03o}", mode)
        }
        Err(_) => String::from("---"),
    }
}

// ANSI helpers
fn clear_screen(out: &mut impl Write) -> io::Result<()> {
    write!(out, "\x1b[2J")
}
fn move_to(out: &mut impl Write, col: u16, row: u16) -> io::Result<()> {
    write!(out, "\x1b[{};{}H", row, col)
}
fn hide_cursor(out: &mut impl Write) -> io::Result<()> {
    write!(out, "\x1b[?25l")
}
fn show_cursor(out: &mut impl Write) -> io::Result<()> {
    write!(out, "\x1b[?25h")
}
fn use_alternate(out: &mut impl Write) -> io::Result<()> {
    write!(out, "\x1b[?1049h")
}
fn leave_alternate(out: &mut impl Write) -> io::Result<()> {
    write!(out, "\x1b[?1049l")
}
fn reset(out: &mut impl Write) -> io::Result<()> {
    write!(out, "\x1b[0m")
}

fn read_key() -> io::Result<Key> {
    let mut buf = [0u8; 1];
    let mut stdin = io::stdin();
    stdin.read_exact(&mut buf)?;
    let c = buf[0];
    if c == 0x1b {
        // Escape or sequence
        // Attempt to read more non-blocking-ish: just try to read another byte.
        let mut b2 = [0u8; 1];
        match stdin.read(&mut b2) {
            Ok(0) => Ok(Key::Esc),
            Ok(_) => {
                if b2[0] == b'[' {
                    let mut b3 = [0u8; 1];
                    stdin.read_exact(&mut b3)?;
                    return Ok(match b3[0] {
                        b'A' => Key::Up,
                        b'B' => Key::Down,
                        b'C' => Key::Right,
                        b'D' => Key::Left,
                        _ => Key::Other,
                    });
                }
                Ok(Key::Esc)
            }
            Err(_) => Ok(Key::Esc),
        }
    } else if c == b'\r' || c == b'\n' {
        Ok(Key::Enter)
    } else if c == 0x7f || c == 0x08 {
        Ok(Key::Backspace)
    } else {
        Ok(Key::Char(c as char))
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum Key {
    Char(char),
    Up, Down, Left, Right,
    Enter, Backspace, Esc, Other,
}

pub fn run(start_path: PathBuf, _log: bool) -> io::Result<()> {
    // Check terminal size
    let (cols, rows) = match terminal_size() {
        Some(sz) => sz,
        None => return Err(io::Error::new(io::ErrorKind::Other, "Cannot detect terminal size")),
    };

    // Enter raw mode
    let _guard = TerminalGuard::enter_raw()?;
    let stdout = io::stdout();
    let mut out = stdout.lock();

    use_alternate(&mut out)?;
    hide_cursor(&mut out)?;
    out.flush()?;

    let mut current = start_path;
    let mut show_hidden = false;
    let mut sort_by_time = false;
    let mut cursor: usize = 0;
    let mut scroll: usize = 0;
    let mut command_mode = false;
    let mut command_buf = String::new();

    let result = loop {
        // Refresh terminal size (simple approach - read once per iteration)
        let (cols, rows) = terminal_size().unwrap_or((cols, rows));
        let entries = match read_entries(&current, show_hidden, sort_by_time) {
            Ok(e) => e,
            Err(_) => Vec::new(),
        };

        if cursor >= entries.len() { cursor = entries.len().saturating_sub(1); }
        let visible_rows = rows.saturating_sub(3) as usize;
        if visible_rows > 0 {
            if cursor < scroll { scroll = cursor; }
            if cursor >= scroll + visible_rows { scroll = cursor + 1 - visible_rows; }
        }

        // Draw
        clear_screen(&mut out)?;
        move_to(&mut out, 1, 1)?;
        let display_dir = current.display().to_string();
        write!(out, " {}", truncate(&display_dir, cols as usize - 1))?;

        let end = (scroll + visible_rows).min(entries.len());
        for (row_idx, i) in (scroll..end).enumerate() {
            let entry = &entries[i];
            let row = (row_idx + 3) as u16;
            move_to(&mut out, 1, row)?;
            let marker = if i == cursor { ">" } else { " " };
            let date_str = format_time(entry.modified);
            let available = cols.saturating_sub(2 + date_str.len() as u16 + 2) as usize;
            let name = truncate(&entry.name, available);
            let padded = format!(" {} {}", marker, name);
            let total_width = cols as usize;
            let used = visual_len(&padded);
            let spaces = if total_width > used + date_str.len() + 1 {
                total_width - used - date_str.len() - 1
            } else { 1 };
            if entry.is_dir {
                write!(out, "\x1b[1;34m{}{}{} \x1b[0m",
                       padded, " ".repeat(spaces), date_str)?;
            } else {
                write!(out, "{}{}{} ", padded, " ".repeat(spaces), date_str)?;
            }
        }

        // Footer
        move_to(&mut out, 1, rows)?;
        if command_mode {
            write!(out, ":{}", command_buf)?;
        } else {
            let total_size: u64 = entries.iter().map(|e| e.size).sum();
            let mode_str = format_mode(&current);
            let sel = if entries.is_empty() { 0 } else { cursor + 1 };
            write!(out, " {}/{} {} {}", sel, entries.len(), format_size(total_size), mode_str)?;
        }

