    fn enter_raw() -> io::Result<Self> {
        unsafe {
            if ffi::isatty(ffi::STDIN_FD) == 0 {
                return Err(io::Error::new(io::ErrorKind::Other, "stdin is not a tty"));
            }
            let mut orig: ffi::Termios = std::mem::zeroed();
            if ffi::tcgetattr(ffi::STDIN_FD, &mut orig) != 0 {
