    let units = ["K", "M", "G", "T", "P"];
    let mut v = n as f64 / 1024.0;
    let mut i = 0usize;
    while v >= 1024.0 && i + 1 < units.len() {
        v /= 1024.0;
        i += 1;
    }
    if v >= 100.0 {
        format!("{:.0}{}", v, units[i])
    } else if v >= 10.0 {
        format!("{:.1}{}", v, units[i])
    } else {
        format!("{:.2}{}", v, units[i])
    }
}

