fn read_key() -> io::Result<Key> {
    let mut buf = [0u8; 1];
    let mut stdin = io::stdin();
    stdin.read_exact(&mut buf)?;
    let c = buf[0];
    if c == 0x1b {
        // Escape or sequence
        // Attempt to read more non-blocking-ish: just try to read another byte.
        let mut b2 = [0u8; 1];
        match stdin.read(&mut b2) {
            Ok(0) => Ok(Key::Esc),
            Ok(_) => {
                if b2[0] == b'[' {
                    let mut b3 = [0u8; 1];
                    stdin.read_exact(&mut b3)?;
                    return Ok(match b3[0] {
                        b'A' => Key::Up,
                        b'B' => Key::Down,
                        b'C' => Key::Right,
                        b'D' => Key::Left,
                        _ => Key::Other,
                    });
                }
                Ok(Key::Esc)
            }
            Err(_) => Ok(Key::Esc),
        }
    } else if c == b'\r' || c == b'\n' {
        Ok(Key::Enter)
    } else if c == 0x7f || c == 0x08 {
        Ok(Key::Backspace)
    } else {
        Ok(Key::Char(c as char))
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum Key {
    Char(char),
    Up, Down, Left, Right,
    Enter, Backspace, Esc, Other,
}

pub fn run(start_path: PathBuf, _log: bool) -> io::Result<()> {
    // Check terminal size
    let (cols, rows) = match terminal_size() {
        Some(sz) => sz,
        None => return Err(io::Error::new(io::ErrorKind::Other, "Cannot detect terminal size")),
    };

    // Enter raw mode
    let _guard = TerminalGuard::enter_raw()?;
    let stdout = io::stdout();
    let mut out = stdout.lock();

    use_alternate(&mut out)?;
    hide_cursor(&mut out)?;
    out.flush()?;

    let mut current = start_path;
    let mut show_hidden = false;
    let mut sort_by_time = false;
    let mut cursor: usize = 0;
    let mut scroll: usize = 0;
    let mut command_mode = false;
    let mut command_buf = String::new();

    let result = loop {
        // Refresh terminal size (simple approach - read once per iteration)
        let (cols, rows) = terminal_size().unwrap_or((cols, rows));
        let entries = match read_entries(&current, show_hidden, sort_by_time) {
            Ok(e) => e,
            Err(_) => Vec::new(),
        };

        if cursor >= entries.len() { cursor = entries.len().saturating_sub(1); }
        let visible_rows = rows.saturating_sub(3) as usize;
        if visible_rows > 0 {
            if cursor < scroll { scroll = cursor; }
            if cursor >= scroll + visible_rows { scroll = cursor + 1 - visible_rows; }
        }

        // Draw
        clear_screen(&mut out)?;
        move_to(&mut out, 1, 1)?;
        let display_dir = current.display().to_string();
        write!(out, " {}", truncate(&display_dir, cols as usize - 1))?;

        let end = (scroll + visible_rows).min(entries.len());
        for (row_idx, i) in (scroll..end).enumerate() {
            let entry = &entries[i];
            let row = (row_idx + 3) as u16;
            move_to(&mut out, 1, row)?;
            let marker = if i == cursor { ">" } else { " " };
            let date_str = format_time(entry.modified);
            let available = cols.saturating_sub(2 + date_str.len() as u16 + 2) as usize;
            let name = truncate(&entry.name, available);
            let padded = format!(" {} {}", marker, name);
            let total_width = cols as usize;
            let used = visual_len(&padded);
            let spaces = if total_width > used + date_str.len() + 1 {
                total_width - used - date_str.len() - 1
            } else { 1 };
            if entry.is_dir {
                write!(out, "\x1b[1;34m{}{}{} \x1b[0m",
                       padded, " ".repeat(spaces), date_str)?;
            } else {
                write!(out, "{}{}{} ", padded, " ".repeat(spaces), date_str)?;
            }
        }

        // Footer
        move_to(&mut out, 1, rows)?;
        if command_mode {
            write!(out, ":{}", command_buf)?;
        } else {
            let total_size: u64 = entries.iter().map(|e| e.size).sum();
            let mode_str = format_mode(&current);
            let sel = if entries.is_empty() { 0 } else { cursor + 1 };
            write!(out, " {}/{} {} {}", sel, entries.len(), format_size(total_size), mode_str)?;
        }

        out.flush()?;

        // Read key
        let key = match read_key() {
            Ok(k) => k,
            Err(_) => break Ok(()),
        };

        if command_mode {
            match key {
                Key::Enter => {
                    let cmd = command_buf.trim().to_string();
                    command_mode = false;
                    command_buf.clear();
                    if cmd == "q" {
                        break Ok(());
                    } else if cmd == "h" {
                        // Show help - for simplicity just continue
                    } else if cmd == "e" {
                        // reload
                    } else if let Some(rest) = cmd.strip_prefix("cd") {
                        let target = rest.trim();
                        let tp = if target.is_empty() {
                            std::env::var_os("HOME").map(PathBuf::from)
                        } else {
                            Some(PathBuf::from(target))
                        };
                        if let Some(p) = tp {
                            if p.is_dir() {
                                current = fs::canonicalize(&p).unwrap_or(p);
                                cursor = 0;
                                scroll = 0;
                            }
                        }
                    }
                }
                Key::Esc => {
                    command_mode = false;
                    command_buf.clear();
                }
                Key::Backspace => { command_buf.pop(); }
                Key::Char(c) => {
                    if (c as u8) == 8 {
                        command_buf.pop();
                    } else if (c as u8) >= 0x20 {
                        command_buf.push(c);
                    }
                }
                _ => {}
            }
            continue;
        }

        match key {
            Key::Char('q') => { /* no-op in normal mode */ }
            Key::Char(':') => {
                command_mode = true;
                command_buf.clear();
            }
            Key::Char('j') | Key::Down => {
                if !entries.is_empty() && cursor + 1 < entries.len() { cursor += 1; }
            }
            Key::Char('k') | Key::Up => {
                if cursor > 0 { cursor -= 1; }
            }
            Key::Char('g') => {
                // wait for second g
                if let Ok(Key::Char('g')) = read_key() { cursor = 0; }
            }
            Key::Char('G') => {
                if !entries.is_empty() { cursor = entries.len() - 1; }
            }
            Key::Char('h') | Key::Left => {
                if let Some(parent) = current.parent() {
                    current = parent.to_path_buf();
                    cursor = 0;
                    scroll = 0;
                }
            }
            Key::Char('l') | Key::Right | Key::Enter => {
                if let Some(e) = entries.get(cursor) {
                    if e.is_dir {
                        current = e.path.clone();
                        cursor = 0;
                        scroll = 0;
                    }
                }
            }
            Key::Backspace => {
                show_hidden = !show_hidden;
                cursor = 0;
            }
            Key::Char('t') => {
                sort_by_time = !sort_by_time;
                cursor = 0;
            }
            Key::Char('Z') => {
                if let Ok(Key::Char(c2)) = read_key() {
                    if c2 == 'Z' || c2 == 'Q' { break Ok(()); }
                }
            }
            _ => {}
        }
    };

    leave_alternate(&mut out)?;
    show_cursor(&mut out)?;
    reset(&mut out)?;
    out.flush()?;
    result
}

fn truncate(s: &str, max: usize) -> String {
    let mut out = String::new();
    let mut n = 0;
    for ch in s.chars() {
        let w = ch_width(ch);
        if n + w > max { break; }
        out.push(ch);
        n += w;
    }
    out
}

fn visual_len(s: &str) -> usize {
    s.chars().map(ch_width).sum()
}

fn ch_width(c: char) -> usize {
    // Very simplified: ASCII = 1, else 1
    if (c as u32) < 0x20 { 0 } else { 1 }
}
